397:     `VADD_VX:         ctrlSignals_0 = {`Y,`N,`N,`B_N,`N,`N,`CSR_N,`Y,`A3_X,   `A2_VRS2,`A1_RS1, `IMM_X,`MEM_X,`FN_ADD,     `N,`M_X,`N,`N,`N,`Y,`N,`N,`N,`N,`N,`N,`N};
