751:     `VADD_VV:         ctrlSignals_1 = {`Y,`N,`N,`B_N,`N,`N,`CSR_N,`Y,`A3_X,   `A2_VRS2,`A1_VRS1,`IMM_X,`MEM_X,`FN_ADD,     `N,`M_X,`N,`N,`N,`Y,`N,`N,`N,`N,`N,`N,`N};
752:     `VADD_VX:         ctrlSignals_1 = {`Y,`N,`N,`B_N,`N,`N,`CSR_N,`Y,`A3_X,   `A2_VRS2,`A1_RS1, `IMM_X,`MEM_X,`FN_ADD,     `N,`M_X,`N,`N,`N,`Y,`N,`N,`N,`N,`N,`N,`N};
753:     `VADD_VI:         ctrlSignals_1 = {`Y,`N,`N,`B_N,`N,`N,`CSR_N,`Y,`A3_X,   `A2_VRS2,`A1_IMM, `IMM_V,`MEM_X,`FN_ADD,     `N,`M_X,`N,`N,`N,`Y,`N,`N,`N,`N,`N,`N,`N};

