11	// Author: Gu, Zihan
12	// Description:scalar alu
13	`timescale 1ns/1ns
14	`include "define.v"
15	module  alu #(
16	  parameter DATA_WIDTH    = 32,
17	  parameter OPCODE_WIDTH  = 5
18	  )
19	  (
20	  //input                         clk,
21	  //input                         rst_n,
